#!/usr/bin/env python3
import subprocess, os, shutil
TB="/tmp/cliarea/tb"
def fresh():
    shutil.rmtree(TB, ignore_errors=True)
    os.makedirs(TB+"/.caps-log/day/y2026", exist_ok=True)
    open(TB+"/.caps-log/config.ini","w").close()
    with open(TB+"/.caps-log/day/y2026/d2026_08_05.md","w") as f:
        f.write("# 05. 08. 2026.\n# Work\n* Coding (rust)\n")
def classify(out):
    if out.startswith(b'\x1b') or b'\x1b[' in out[:200]:
        return "TUI-STARTED"
    return None
def run(args, env=None, label=None, freshtb=True, timeout=6, stdin=b'', full=False):
    if freshtb: fresh()
    e={'HOME':TB,'PATH':'/usr/bin:/bin','TERM':'dumb'}
    if env: e.update(env)
    to=False
    try:
        p=subprocess.run(['/workspace/executable']+args, env=e, capture_output=True, timeout=timeout, input=stdin)
        rc=p.returncode; out=p.stdout; err=p.stderr
    except subprocess.TimeoutExpired as t:
        rc='TIMEOUT'; out=t.stdout or b''; err=t.stderr or b''; to=True
    print("### %s | argv=%r | exit=%s" % (label or '', args, rc))
    c=classify(out)
    if c and not full:
        print("    STDOUT: %s (%d bytes, escape sequences)" % (c, len(out)))
    else:
        if not out: print("    STDOUT: <empty>")
        else:
            print("    STDOUT (%d bytes):"%len(out))
            for l in out.decode('utf-8','replace').split('\n'): print("      |%s|"%l)
    if not err: print("    STDERR: <empty>")
    else:
        print("    STDERR (%d bytes): %r"%(len(err),err))
    print()
    return rc,out,err
PY
