import subprocess, os, shutil
BASE="/tmp/cliarea/dp"
def snap(root):
    out=[]
    for dp,dns,fns in os.walk(root):
        for d in sorted(dns): out.append(os.path.join(dp,d)+"/")
        for f in sorted(fns): out.append(os.path.join(dp,f))
    return sorted(out)
def run(args, mk=None, label='', timeout=4, env=None, cfg=''):
    shutil.rmtree(BASE, ignore_errors=True)
    os.makedirs(BASE+"/.caps-log", exist_ok=True)
    open(BASE+"/.caps-log/config.ini","w").write(cfg)
    if mk: 
        for m in mk: os.makedirs(BASE+"/"+m, exist_ok=True)
    before=snap(BASE)
    e={'HOME':BASE,'PATH':'/usr/bin:/bin','TERM':'dumb'}
    if env: e.update(env)
    try:
        p=subprocess.run(['/workspace/executable']+args, env=e, capture_output=True, timeout=timeout, input=b'')
        rc=p.returncode; out=p.stdout; err=p.stderr
    except subprocess.TimeoutExpired as t:
        rc='TIMEOUT'; out=t.stdout or b''; err=t.stderr or b''
    after=snap(BASE)
    new=[x[len(BASE):] for x in after if x not in before]
    print("### %s | argv=%r | exit=%s"%(label,args,rc))
    print("    NEW PATHS: %r"%(new,))
    if err: print("    STDERR: %r"%err)
    if out and not out.startswith(b'\x1b'): print("    STDOUT: %r"%out[:400])
    elif out: print("    STDOUT: TUI (%d bytes)"%len(out))
    print()
PY
